-- ============================================================================
-- MIS Review fact tables (Revenue Forecast project)
-- MySQL-style standalone SQL, same format as banquet.sql
--
-- Business meaning
--   fact_forecast_accuracy : one row per company-quarter -- actual revenue vs
--                            chosen/ridge/naive forecasts, variance %, RAG zone
--   fact_company_league    : one row per company   -- full-period accuracy, ranked
--   fact_error_by_year     : one row per year      -- MAPE per model + mortgage rate
--
-- Provenance
--   Generated by scripts/make_tableau_export.py (DuckDB over audited parquet
--   artifacts; SEC EDGAR companyfacts + FRED MORTGAGE30US). The publication
--   copies live in outputs/tableau/*.csv; this file mirrors them in plain
--   MySQL for review, prototyping and BI-tool ingestion.
--
-- Model column legend
--   fc_chosen = seasonal_drift (the pre-registered finalist that stood after the
--               locked test), fc_ridge = ridge_drivers, fc_naive = naive_last
-- ============================================================================

CREATE DATABASE MIS_Review_db;
USE MIS_Review_db;

#creating tables
DROP TABLE IF EXISTS fact_forecast_accuracy;
CREATE TABLE fact_forecast_accuracy (
    ticker        VARCHAR(10)  NOT NULL,
    sector        VARCHAR(20)  NOT NULL,
    quarter_end   DATE         NOT NULL,
    year          SMALLINT     NOT NULL,
    quarter_num   TINYINT      NOT NULL,
    actual        DECIMAL(18,2) NOT NULL,
    fc_chosen     DECIMAL(18,2) NOT NULL,
    fc_ridge      DECIMAL(18,2) NOT NULL,
    fc_naive      DECIMAL(18,2) NOT NULL,
    var_chosen_pct DECIMAL(6,2) NOT NULL,
    var_ridge_pct  DECIMAL(6,2) NOT NULL,
    zone_chosen   VARCHAR(9)   NOT NULL CHECK (zone_chosen IN ('on plan','review','escalate')),
    within_5pct   TINYINT      NOT NULL CHECK (within_5pct IN (0,1)),
    PRIMARY KEY (ticker, quarter_end)
);

DROP TABLE IF EXISTS fact_company_league;
CREATE TABLE fact_company_league (
    ticker            VARCHAR(10)  PRIMARY KEY,
    sector            VARCHAR(20)  NOT NULL,
    n_quarters        SMALLINT     NOT NULL,
    mape_chosen_pct   DECIMAL(6,2) NOT NULL,
    within_5pct_share DECIMAL(5,1) NOT NULL,
    mape_ridge_pct    DECIMAL(6,2) NOT NULL,
    chosen_minus_ridge DECIMAL(6,2) NOT NULL,
    ease_rank         TINYINT      NOT NULL
);

DROP TABLE IF EXISTS fact_error_by_year;
CREATE TABLE fact_error_by_year (
    year              SMALLINT     PRIMARY KEY,
    mape_chosen_pct   DECIMAL(6,2) NOT NULL,
    mape_ridge_pct    DECIMAL(6,2) NOT NULL,
    mape_naive_pct    DECIMAL(6,2) NOT NULL,
    avg_mortgage_rate DECIMAL(4,2) NOT NULL
);

